1: /** @module @category Feature Flags */
2: import { useStore } from './useStore';
3: import { featureFlagsStore } from '@openmrs/esm-feature-flags';
4: 
5: /** Use this function to tell whether a feature flag is toggled on or off.
6:  *
7:  * Example:
8:  *
9:  * ```tsx
10:  * import { useFeatureFlag } from "@openmrs/esm-react-utils";
11:  *
12:  * export function MyComponent() {
13:  *  const isMyFeatureFlagOn = useFeatureFlag("my-feature-flag");
14:  *  return <>{isMyFeatureFlagOn && <ExperimentalFeature />}</>;
15:  * }
16:  * ```
17:  */
18: export function useFeatureFlag(flagName: string) {
19:   const { flags } = useStore(featureFlagsStore);
20: 
21:   // Return false if flag does not exist or if it's off
22:   return flags[flagName]?.enabled ?? false;
23: }
