1: /** @module @category Feature Flags */
2: import { getGlobalStore } from '@openmrs/esm-state';
3: 
4: export interface FeatureFlagsStore {
5:   flags: { [flagName: string]: FeatureFlag };
6: }
7: 
8: export interface FeatureFlag {
9:   enabled: boolean;
10:   label: string;
11:   description: string;
12: }
13: 
14: const initialFeatureFlags = { flags: getFeatureFlagsFromLocalStorage() };
15: 
16: /** @internal */
17: export const featureFlagsStore = getGlobalStore<FeatureFlagsStore>('feature-flags', initialFeatureFlags);
18: 
19: featureFlagsStore.subscribe((state) => {
20:   for (const [flagName, flag] of Object.entries(state.flags)) {
21:     localStorage.setItem(`openmrs:feature-flag:${flagName}`, flag.enabled.toString());
22:     localStorage.setItem(
23:       `openmrs:feature-flag-meta:${flagName}`,
24:       JSON.stringify({ label: flag.label, description: flag.description }),
25:     );
26:   }
27: });
28: 
29: function getFeatureFlagsFromLocalStorage() {
30:   const flags: FeatureFlagsStore['flags'] = {};
31:   for (const key of Object.keys(localStorage)) {
32:     if (key.startsWith('openmrs:feature-flag:')) {
33:       const flagName = key.replace('openmrs:feature-flag:', '');
34:       const meta = JSON.parse(localStorage.getItem(`openmrs:feature-flag-meta:${flagName}`) || '{}');
35:       flags[flagName] = {
36:         enabled: localStorage.getItem(key) === 'true',
37:         ...meta,
38:       };
39:     }
40:   }
41:   return flags;
42: }
43: 
44: /**
45:  * This function creates a feature flag. Call it in top-level code anywhere. It will
46:  * not reset whether the flag is enabled or not, so it's safe to call it multiple times.
47:  * Once a feature flag is created, it will appear with a toggle in the Implementer Tools.
48:  * It can then be used to turn on or off features in the code.
49:  *
50:  * @param flagName A code-friendly name for the flag, which will be used to reference it in code
51:  * @param label A human-friendly name which will be displayed in the Implementer Tools
52:  * @param description An explanation of what the flag does, which will be displayed in the Implementer Tools
53:  */
54: export function registerFeatureFlag(flagName: string, label: string, description: string) {
55:   featureFlagsStore.setState((state) => ({
56:     flags: {
57:       ...state.flags,
58:       [flagName]: {
59:         enabled: state.flags[flagName]?.enabled ?? false,
60:         label,
61:         description,
62:       },
63:     },
64:   }));
65: }
66: 
67: /**
68:  * This function removes feature flags from local storage that no longer exist in the current state.
69:  */
70: export function cleanupObsoleteFeatureFlags() {
71:   const flags = featureFlagsStore.getState().flags;
72:   Object.keys(localStorage)
73:     .filter((key) => key.startsWith('openmrs:feature-flag:'))
74:     .forEach((key) => {
75:       const flagName = key.replace('openmrs:feature-flag:', '');
76:       if (!flags[flagName]) {
77:         localStorage.removeItem(key);
78:         localStorage.removeItem(`openmrs:feature-flag-meta:${flagName}`);
79:       }
80:     });
81: }
82: 
83: /**
84:  * Use this function to access the current value of the feature flag.
85:  *
86:  * If you are using React, use `useFeatureFlag` instead.
87:  *
88:  * @param flagName The name of the feature flag to check.
89:  * @returns `true` if the feature flag is enabled, `false` otherwise.
90:  */
91: export function getFeatureFlag(flagName: string) {
92:   return featureFlagsStore.getState().flags[flagName].enabled;
93: }
94: 
95: /**
96:  * Use this function to subscribe to the value of the feature flag.
97:  * The callback will be invoked immediately with the current value and
98:  * again whenever the flag value changes.
99:  *
100:  * If you are using React, use `useFeatureFlag` instead.
101:  *
102:  * @param flagName The name of the feature flag to subscribe to.
103:  * @param callback A function that will be called with the current flag value.
104:  */
105: export function subscribeToFeatureFlag(flagName: string, callback: (value: boolean) => void) {
106:   featureFlagsStore.subscribe((state) => {
107:     callback(state.flags[flagName].enabled);
108:   });
109: }
110: 
111: /** @internal for Implementer Tools */
112: export function setFeatureFlag(flagName: string, value: boolean) {
113:   featureFlagsStore.setState((state) => ({
114:     flags: {
115:       ...state.flags,
116:       [flagName]: { ...state.flags[flagName], enabled: value },
117:     },
118:   }));
119: }
