103:  * @param callback A function that will be called with the current flag value.
104:  */
105: export function subscribeToFeatureFlag(flagName: string, callback: (value: boolean) => void) {
106:   featureFlagsStore.subscribe((state) => {
107:     callback(state.flags[flagName].enabled);
108:   });
109: }
